{
  "root": "main_stack",
  "state": {
    "comparison_table_data": [
      {
        "restaurant": "Izusen",
        "price": "~7,000 JPY",
        "vegetarian_friendly": "100% (Shojin Ryori)",
        "atmosphere": "Extremely Peaceful",
        "ranking": "#1"
      },
      {
        "restaurant": "Gion Karyo",
        "price": "~12,000 JPY",
        "vegetarian_friendly": "Yes (With notice)",
        "atmosphere": "Intimate/Traditional",
        "ranking": "#2"
      },
      {
        "restaurant": "Chao Chao",
        "price": "~3,500 JPY",
        "vegetarian_friendly": "Very Poor",
        "atmosphere": "Loud/Energetic",
        "ranking": "#3"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "ranking_heading",
        "ranking_list_stack",
        "comparison_table_heading",
        "comparison_table",
        "recommendation_heading_stack",
        "recommendation_card",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Kyoto Traditional Dining Comparison",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "For your group of 4 on November 15, 2024, prioritizing a 5k-15k JPY budget, vegetarian options, and a quiet atmosphere:",
        "variant": "body"
      },
      "children": []
    },
    "ranking_heading": {
      "type": "Text",
      "props": {
        "text": "Restaurant Suitability Ranking",
        "variant": "h2"
      },
      "children": []
    },
    "ranking_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ranking_item_1",
        "ranking_item_2",
        "ranking_item_3"
      ]
    },
    "ranking_item_1": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "ranking_item_1_title",
        "ranking_item_1_reason"
      ]
    },
    "ranking_item_1_title": {
      "type": "Text",
      "props": {
        "text": "1. Izusen at Daiji-in | Best Fit",
        "variant": "body"
      },
      "children": []
    },
    "ranking_item_1_reason": {
      "type": "Text",
      "props": {
        "text": "Reason: This is 100% vegetarian Buddhist cuisine (Shojin Ryori) in a quiet temple garden. At 7,000 JPY, it is perfectly within your budget and offers the most traditional, peaceful experience.",
        "variant": "caption"
      },
      "children": []
    },
    "ranking_item_2": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "ranking_item_2_title",
        "ranking_item_2_reason"
      ]
    },
    "ranking_item_2_title": {
      "type": "Text",
      "props": {
        "text": "2. Gion Karyo | Good Alternative",
        "variant": "body"
      },
      "children": []
    },
    "ranking_item_2_reason": {
      "type": "Text",
      "props": {
        "text": "Reason: Offers high-end Kaiseki with a dedicated vegetarian menu (12,000 JPY). The intimate townhouse setting is very traditional, though it requires advance notice.",
        "variant": "caption"
      },
      "children": []
    },
    "ranking_item_3": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "ranking_item_3_title",
        "ranking_item_3_reason"
      ]
    },
    "ranking_item_3_title": {
      "type": "Text",
      "props": {
        "text": "3. Chao Chao Sanjo Kiyamachi | Least Suitable",
        "variant": "body"
      },
      "children": []
    },
    "ranking_item_3_reason": {
      "type": "Text",
      "props": {
        "text": "Reason: Fails almost all criteria. It is loud, has very few vegetarian items, and focuses on casual gyoza rather than a traditional atmosphere.",
        "variant": "caption"
      },
      "children": []
    },
    "comparison_table_heading": {
      "type": "Text",
      "props": {
        "text": "Comparison Summary Table",
        "variant": "h2"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "restaurant",
            "label": "Restaurant"
          },
          {
            "key": "price",
            "label": "Price"
          },
          {
            "key": "vegetarian_friendly",
            "label": "Vegetarian Friendly"
          },
          {
            "key": "atmosphere",
            "label": "Atmosphere"
          },
          {
            "key": "ranking",
            "label": "Ranking"
          }
        ],
        "statePath": "/comparison_table_data",
        "domain": "comparison",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "recommendation_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": ["recommendation_heading_text", "recommendation_icon"]
    },
    "recommendation_heading_text": {
      "type": "Text",
      "props": {
        "text": "Our Top Recommendation",
        "variant": "h2"
      },
      "children": []
    },
    "recommendation_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.5/icons/star-fill.svg"
      },
      "children": []
    },
    "recommendation_card": {
      "type": "Card",
      "props": {},
      "children": [
        "recommendation_card_title",
        "recommendation_card_text_1",
        "recommendation_card_text_2",
        "recommendation_card_button"
      ]
    },
    "recommendation_card_title": {
      "type": "Text",
      "props": {
        "text": "Izusen at Daiji-in",
        "variant": "h3"
      },
      "children": []
    },
    "recommendation_card_text_1": {
      "type": "Text",
      "props": {
        "text": "Experience authentic Shojin Ryori (Buddhist vegetarian cuisine) in a serene temple garden setting. Perfect for a peaceful dining experience.",
        "variant": "body"
      },
      "children": []
    },
    "recommendation_card_text_2": {
      "type": "Text",
      "props": {
        "text": "Price: ~7,000 JPY per person. Vegetarian-friendly: 100%. Atmosphere: Extremely Peaceful.",
        "variant": "caption"
      },
      "children": []
    },
    "recommendation_card_button": {
      "type": "Button",
      "props": {
        "label": "Book Izusen"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.izusen.jp/en/"
          }
        }
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "action_button_1",
        "action_button_2"
      ]
    },
    "action_button_1": {
      "type": "Button",
      "props": {
        "label": "Explore More Kyoto Restaurants"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e3900.html"
          }
        }
      },
      "children": []
    },
    "action_button_2": {
      "type": "Button",
      "props": {
        "label": "Plan Your Kyoto Trip"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan-guide.com/e/e2158.html"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_link_1",
        "source_link_2",
        "source_link_3"
      ]
    },
    "source_link_1": {
      "type": "Button",
      "props": {
        "label": "Izusen Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.izusen.jp/en/"
          }
        }
      },
      "children": []
    },
    "source_link_2": {
      "type": "Button",
      "props": {
        "label": "Gion Karyo Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://gionkaryo.com/en/"
          }
        }
      },
      "children": []
    },
    "source_link_3": {
      "type": "Button",
      "props": {
        "label": "Chao Chao Gyoza Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.chaochao.jp/en/"
          }
        }
      },
      "children": []
    }
  }
}
